# Import of required libraries
import skyramp
import os
import time

from SkyrampUtils import create_flow, create_flow_run, get_flow_runs_list


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:4200")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["X-Admin-Key"] = os.getenv("SKYRAMP_TEST_TOKEN")

    flow_POST_response = create_flow(client, headers, "skyramp-size-only-flow")
    flow_id = skyramp.get_response_value(flow_POST_response, "id")
    assert len(flow_id) == 36
    assert flow_id.count("-") == 4

    flow_run_1_POST_response = create_flow_run(client, headers, flow_id, "size-only-run-1")
    assert skyramp.get_response_value(flow_run_1_POST_response, "name") == "size-only-run-1"
    assert skyramp.get_response_value(flow_run_1_POST_response, "flow_id") == flow_id
    assert skyramp.get_response_value(flow_run_1_POST_response, "state_type") == "PENDING"
    assert skyramp.get_response_value(flow_run_1_POST_response, "state_name") == "Pending"
    flow_run_1_id = skyramp.get_response_value(flow_run_1_POST_response, "id")
    assert len(flow_run_1_id) == 36

    flow_run_2_POST_response = create_flow_run(client, headers, flow_id, "size-only-run-2")
    assert skyramp.get_response_value(flow_run_2_POST_response, "name") == "size-only-run-2"
    assert skyramp.get_response_value(flow_run_2_POST_response, "flow_id") == flow_id
    assert skyramp.get_response_value(flow_run_2_POST_response, "state_type") == "PENDING"
    assert skyramp.get_response_value(flow_run_2_POST_response, "state_name") == "Pending"
    flow_run_2_id = skyramp.get_response_value(flow_run_2_POST_response, "id")
    assert len(flow_run_2_id) == 36
    assert flow_run_2_id != flow_run_1_id

    filter_POST_response = get_flow_runs_list(
        client, headers, flow_id, {"page_size": 2}
    )
    assert skyramp.get_response_value(filter_POST_response, "0.id")
    assert skyramp.get_response_value(filter_POST_response, "1.id")
    assert not skyramp.get_response_value(filter_POST_response, "2.id")
    assert skyramp.get_response_value(filter_POST_response, "0.name") == "size-only-run-1"
    assert skyramp.get_response_value(filter_POST_response, "1.name") == "size-only-run-2"
    first_page_ids = [
        skyramp.get_response_value(filter_POST_response, "0.id"),
        skyramp.get_response_value(filter_POST_response, "1.id"),
    ]
    assert first_page_ids == [flow_run_1_id, flow_run_2_id]


if __name__ == "__main__":
    test_integration()
